const post=(action:string,data:Record<string,unknown>)=>api(action,data,'/api/store-operations');
const money=(v:number|null)=>v===null?'미확인':v.toLocaleString('ko-KR',{maximumFractionDigits:0})+'원';
const states={unknown:'미확인',todo:'보완 필요',done:'확인 완료',stale:'재확인 필요'};
function Field({label,children}:{label:string;children:ReactNode}){return <label className="store-field"><span>{label}</span>{children}</label>}
async function read(storeId:string,period?:{from:string;to:string},part?:string){const q=new URLSearchParams({storeId,...period,...(part?{part}:{})});const res=await fetch('/api/store-operations?'+q);const data=await res.json() as StoreOperations & {error?:string};if(!res.ok)throw new Error(data.error||'매장 기록을 불러오지 못했습니다.');return data as StoreOperations}

export function StoreDiagnosticPanel({store}:{store:Store}){
 const [records,setRecords]=useState<StoreDiagnostic[]>([]),[editing,setEditing]=useState<string|null>(null),[error,setError]=useState(''),[loading,setLoading]=useState(true);
 const load=useCallback(async()=>{try{const d=await read(store.id,undefined,'diagnosis');setRecords(d.diagnostics);setError('')}catch(e){setError((e as Error).message)}finally{setLoading(false)}},[store.id]);
 useEffect(()=>{void load()},[load]);
 const confirmed=records.filter(r=>diagnosisStatus(r,store)==='done').length;
 return <section className="store-operating-check"><div className="section-heading"><div><h3>매장 실행 준비 <span className="store-tag">{confirmed}/{diagnosisCatalog.length} 확인</span></h3><p>실제로 확인한 근거와 다음 행동을 기록합니다.</p></div></div>{error&&<p className="load-error" role="alert">{error}<Button variant="outline" onClick={()=>void load()}>다시 시도</Button></p>}{loading?<p role="status">확인 기록을 불러오고 있습니다.</p>:<div className="store-diagnostic-grid">{diagnosisCatalog.map(item=>{const r=records.find(x=>x.key===item.key),state=diagnosisStatus(r,store);return <article key={item.key}><div><span className={'store-tag '+(state==='done'?'done':'')}>{states[state]}</span><h4>{item.title}</h4></div><p>{r?.observation||item.prompt}</p>{r?.nextAction&&<p className="diagnostic-next"><b>다음 행동</b> {r.nextAction}</p>}{r?.assignee&&<small>담당 · {r.assignee}</small>}{state==='stale'&&<p className="notice">지점 정보가 바뀌었습니다. 근거를 다시 확인하세요.</p>}<footer><small>{r?.checkedAt||'확인일 미등록'}</small><Button variant="outline" disabled={!!error} onClick={()=>setEditing(item.key)}>확인·기록</Button></footer></article>})}</div>}{editing&&<DiagnosticDialog key={editing} store={store} itemKey={editing} initial={records.find(r=>r.key===editing)} onClose={()=>setEditing(null)} onSaved={load}/>}</section>;
}
function DiagnosticDialog({store,itemKey,initial,onClose,onSaved}:{store:Store;itemKey:string;initial?:StoreDiagnostic;onClose:()=>void;onSaved:()=>Promise<void>}){
 const item=diagnosisCatalog.find(x=>x.key===itemKey)!,[f,setF]=useState({key:item.key,status:initial?.status||'unknown',observation:initial?.observation||'',evidence:initial?.evidence||'',checkedAt:initial?.checkedAt||koreaToday(),nextAction:initial?.nextAction||'',assignee:initial?.assignee||''}),[busy,setBusy]=useState(false);
 return <Dialog open onOpenChange={v=>!v&&!busy&&onClose()}><DialogContent className="wide-dialog"><DialogHeader><DialogTitle>{item.title}</DialogTitle><DialogDescription>{item.hint}</DialogDescription></DialogHeader><form className="form-stack" onSubmit={async e=>{e.preventDefault();setBusy(true);try{await post('save_diagnostic',{storeId:store.id,storeVersion:store.version,version:initial?.version,data:f});await onSaved();onClose();toast.success('매장 확인 기록을 저장했습니다.')}catch(e){toast.error((e as Error).message)}finally{setBusy(false)}}}><Field label="확인 상태"><NativeSelect value={f.status} onChange={e=>setF({...f,status:e.target.value as typeof f.status})}>{(['unknown','todo','done'] as const).map(k=><NativeSelectOption key={k} value={k}>{states[k]}</NativeSelectOption>)}</NativeSelect></Field>{Object.entries({observation:'확인한 내용',evidence:'실제 근거 · 자료 또는 확인 방법',nextAction:'다음에 할 일'}).map(([k,label])=><Field key={k} label={label}><Textarea required={f.status==='done'&&k!=='nextAction'} rows={3} maxLength={k==='observation'?4000:k==='evidence'?3000:2000} value={f[k as keyof typeof f]} onChange={e=>setF({...f,[k]:e.target.value})}/></Field>)}<div className="form-two"><Field label="확인일"><Input type="date" max={koreaToday()} required={f.status==='done'} value={f.checkedAt} onChange={e=>setF({...f,checkedAt:e.target.value})}/></Field><Field label="담당자"><Input maxLength={100} value={f.assignee} onChange={e=>setF({...f,assignee:e.target.value})}/></Field></div><Button disabled={busy}>{busy?<LoaderCircle className="spin"/>:<Check/>}확인 기록 저장</Button></form></DialogContent></Dialog>;
}

function LedgerBook({store,experiments,onImport}:{store:Store;experiments:StoreExperiment[];onImport?:()=>void}){
 const [period,setPeriod]=useState(recentPeriod),[range,setRange]=useState(recentPeriod),[data,setData]=useState<StoreOperations>(emptyOperations),[loading,setLoading]=useState(true),[error,setError]=useState(''),[order,setOrder]=useState<StoreOrder|'new'|null>(null),[spend,setSpend]=useState<StoreSpend|'new'|null>(null),[importing,setImporting]=useState(false),[filter,setFilter]=useState('all');
 const load=useCallback(async()=>{setLoading(true);try{setData(await read(store.id,period));setError('')}catch(e){setError((e as Error).message)}finally{setLoading(false)}},[store.id,period]);useEffect(()=>{void load()},[load]);
 const summary=ledgerSummary(data.orders,data.spend),visible=data.orders.filter(o=>filter==='all'||(filter==='unknown'?o.channel==='unknown'&&!o.campaignId&&!o.creativeId:o.experimentId===filter));
 return <section><div className="section-heading"><div><h3>주문 성과 장부</h3><p>주문별 실제 결제·환불·비용과 유입 근거를 연결합니다.</p></div><div className="store-actions"><Button variant="outline" onClick={()=>setImporting(true)}><Upload/>장부 양식 CSV</Button>{onImport&&<Button variant="outline" onClick={onImport}><Upload/>POS CSV 가져오기</Button>}<Button onClick={()=>setOrder('new')}><Plus/>주문 기록</Button></div></div><form className="ledger-period" onSubmit={e=>{e.preventDefault();setPeriod({...range})}}><Field label="주문일 시작"><Input type="date" required value={range.from} max={range.to} onChange={e=>setRange({...range,from:e.target.value})}/></Field><Field label="주문일 종료"><Input type="date" required value={range.to} min={range.from} max={koreaToday()} onChange={e=>setRange({...range,to:e.target.value})}/></Field><Button variant="outline" disabled={loading}><RefreshCw/>조회</Button></form>
 {error?<div className="load-error" role="alert">{error}<Button variant="outline" onClick={()=>void load()}>다시 시도</Button></div>:loading?<p role="status">장부를 불러오고 있습니다.</p>:<><div className="ledger-summary"><article><span>유효 주문</span><strong>{summary.orders}건</strong><small>취소 {summary.cancelled} · 전액 환불 {summary.refunded}</small></article><article><span>환불 차감 매출</span><strong>{money(summary.netRevenue)}</strong><small>입력한 주문 {summary.records}건 기준</small></article><article><span>입력분 기여잔액</span><strong>{summary.records?money(summary.recordedBalance):'미수집'}</strong><small>비용 확인 {summary.knownCosts}/{summary.records}건 · 입력 광고·제작비 차감</small></article><article><span>유입 경로 확인</span><strong>{summary.orders?Math.round(summary.attributed/summary.orders*100)+'%':'미수집'}</strong><small>{summary.attributed}/{summary.orders}건 · 실제 광고 순증 효과와 구분</small></article></div><p className="notice">장부에 입력한 범위의 집계입니다. 전체 매출·영업이익으로 해석하지 마세요. 빈 원가는 미확인으로 유지하며, 비용이 없음을 확인한 항목만 0으로 입력합니다.</p><div className="ledger-filter"><Field label="주문 보기"><NativeSelect value={filter} onChange={e=>setFilter(e.target.value)}><NativeSelectOption value="all">전체 주문</NativeSelectOption><NativeSelectOption value="unknown">유입 경로 미확인</NativeSelectOption>{experiments.map(e=><NativeSelectOption key={e.id} value={e.id}>{e.title}</NativeSelectOption>)}</NativeSelect></Field><small>{data.from} ~ {data.to}</small></div>
 {!visible.length?<div className="store-empty"><h3>이 조건의 주문 기록이 없습니다</h3><p>POS 자료를 양식에 맞춰 가져오거나 주문을 직접 기록하세요.</p></div>:<div className="ledger-table-wrap"><table className="ledger-table"><caption className="sr-only">선택 기간의 주문 성과</caption><thead><tr><th>주문</th><th>상태·방식</th><th>환불 차감 매출</th><th>주문 기여이익</th><th>유입·실험</th><th>수정</th></tr></thead><tbody>{visible.slice(0,200).map(o=><tr key={o.id}><td><b>{o.orderNumber}</b><small>{o.orderDate} · {orderSources[o.source]}</small></td><td>{orderStates[o.status]}<small>{orderModes[o.mode]}</small></td><td>{money(o.paidAmount-o.refundAmount)}{o.refundAmount>0&&<small>환불 {money(o.refundAmount)}</small>}</td><td>{money(orderContribution(o))}</td><td>{channelCatalog.find(c=>c.key===o.channel)?.name||'미확인'}<small>{experiments.find(e=>e.id===o.experimentId)?.title||'실험 미연결'}</small></td><td><Button variant="ghost" aria-label={o.orderNumber+' 주문 수정'} onClick={()=>setOrder(o)}><Pencil/></Button></td></tr>)}</tbody></table></div>}{visible.length>200&&<p className="notice">집계는 {visible.length}건 전체를 반영합니다. 표는 최근 200건이며 이전 주문은 조회 기간을 좁혀 확인하세요.</p>}
 <div className="section-heading"><div><h3>광고·제작 비용</h3><p>광고비 {money(summary.adSpend)} · 제작·협찬비 {money(summary.productionCost)} 입력됨</p></div><Button variant="outline" onClick={()=>setSpend('new')}><Plus/>비용 기록</Button></div>{!data.spend.length?<p className="notice">입력된 비용이 없습니다. 비용이 발생하지 않았다는 의미는 아닙니다.</p>:<div className="ledger-spends">{data.spend.map(s=><article key={s.id}><div><b>{s.date} · {channelCatalog.find(c=>c.key===s.channel)?.name}</b><p>{s.source}</p><small>{experiments.find(e=>e.id===s.experimentId)?.title||'실험 미연결'} · 광고 {money(s.adSpend)} / 제작 {money(s.productionCost)}</small></div><Button variant="outline" onClick={()=>setSpend(s)}>수정</Button></article>)}</div>}<CollectedSpend store={store} experiments={experiments} onSaved={load}/></>}
 {order&&<OrderDialog store={store} experiments={experiments} initial={order==='new'?undefined:order} onClose={()=>setOrder(null)} onSaved={load}/>} {spend&&<SpendDialog store={store} experiments={experiments} initial={spend==='new'?undefined:spend} onClose={()=>setSpend(null)} onSaved={load}/>} {importing&&<ImportDialog store={store} onClose={()=>setImporting(false)} onSaved={load}/>}</section>;
}
function Attribution({f,setF,experiments,allowUnknown=true}:{f:{channel:string;experimentId:string};setF:(x:{channel:string;experimentId:string})=>void;experiments:StoreExperiment[];allowUnknown?:boolean}){return <div className="form-two"><Field label="확인한 유입 채널"><NativeSelect value={f.channel} onChange={e=>setF({channel:e.target.value,experimentId:''})}>{allowUnknown&&<NativeSelectOption value="unknown">미확인</NativeSelectOption>}{channelCatalog.map(c=><NativeSelectOption key={c.key} value={c.key}>{c.name}</NativeSelectOption>)}</NativeSelect></Field><Field label="연결할 실험"><NativeSelect value={f.experimentId} onChange={e=>{const exp=experiments.find(x=>x.id===e.target.value);setF({channel:exp?.channel||f.channel,experimentId:e.target.value})}}><NativeSelectOption value="">실험 미연결</NativeSelectOption>{experiments.filter(e=>e.status!=='draft').map(e=><NativeSelectOption key={e.id} value={e.id}>{e.title}{e.status==='completed'?' · 회고 완료':''}</NativeSelectOption>)}</NativeSelect></Field></div>}
function OrderDialog({store,experiments,initial,onClose,onSaved}:{store:Store;experiments:StoreExperiment[];initial?:StoreOrder;onClose:()=>void;onSaved:()=>Promise<void>}){
 const [f,setF]=useState({source:initial?.source||'pos',orderNumber:initial?.orderNumber||'',orderDate:initial?.orderDate||koreaToday(),mode:initial?.mode||'hall',status:initial?.status||'paid',paidAmount:initial?.paidAmount.toString()||'',refundAmount:initial?.refundAmount.toString()||'0',channel:initial?.channel||'unknown',experimentId:initial?.experimentId||'',campaignId:initial?.campaignId||'',creativeId:initial?.creativeId||'',trackingCode:'',attributionEvidence:initial?.attributionEvidence||'',note:initial?.note||''}),[costs,setCosts]=useState<Record<string,string>>(Object.fromEntries(Object.keys(orderCostFields).map(k=>[k,initial?.costs[k as keyof typeof orderCostFields]?.toString()??'']))),[busy,setBusy]=useState(false);
 // A4-3 추적 코드 칸: 서버가 코드를 조회해 캠페인·소재(게시)를 채운다. 비우면 기존 수동 귀속 그대로다(고칠 때도 칸 없음과 같은 기존 사본 규칙). 그래서 칸은 비워 열고, 지금 귀속한 코드는 안내에만 보인다.
 // 귀속하지 못한 사유와 게시 기록 없는 소재 경고는 저장 뒤 알린다.
 const coded=!!f.trackingCode.trim(),readCodes=(initial?.trackingCodes||[]).filter(c=>c!==initial?.codeAttribution?.code);
 return <Dialog open onOpenChange={v=>!v&&!busy&&onClose()}><DialogContent className="wide-dialog"><DialogHeader><DialogTitle>{initial?'주문 기록 수정':'주문 기록'}</DialogTitle><DialogDescription>출처·주문일·주문번호가 같은 주문은 한 번만 등록됩니다.</DialogDescription></DialogHeader><form className="form-stack" onSubmit={async e=>{e.preventDefault();setBusy(true);try{const r=await post('save_order',{storeId:store.id,id:initial?.id,version:initial?.version,data:{...f,costs}}) as unknown as {attribution?:EntryView};await onSaved();onClose();const a=r.attribution;toast.success('주문 기록을 저장했습니다.',a?.via==='code'&&a.code?{description:`추적 코드 ${a.code}로 귀속했습니다.`}:undefined);if(a?.warning)toast.warning(a.warning,{duration:12000})}catch(e){toast.error((e as Error).message)}finally{setBusy(false)}}}><div className="form-two"><Field label="주문 출처"><NativeSelect disabled={!!initial} value={f.source} onChange={e=>setF({...f,source:e.target.value as typeof f.source})}>{Object.entries(orderSources).map(([k,v])=><NativeSelectOption key={k} value={k}>{v}</NativeSelectOption>)}</NativeSelect></Field><Field label="출처의 주문번호"><Input required disabled={!!initial} maxLength={100} value={f.orderNumber} onChange={e=>setF({...f,orderNumber:e.target.value})}/></Field><Field label="원래 주문일 · 한국시간"><Input required disabled={!!initial} type="date" max={koreaToday()} value={f.orderDate} onChange={e=>setF({...f,orderDate:e.target.value})}/></Field><Field label="주문 방식"><NativeSelect value={f.mode} onChange={e=>setF({...f,mode:e.target.value as typeof f.mode})}>{Object.entries(orderModes).map(([k,v])=><NativeSelectOption key={k} value={k}>{v}</NativeSelectOption>)}</NativeSelect></Field><Field label="상태"><NativeSelect value={f.status} onChange={e=>setF({...f,status:e.target.value as typeof f.status})}>{Object.entries(orderStates).map(([k,v])=><NativeSelectOption key={k} value={k}>{v}</NativeSelectOption>)}</NativeSelect></Field><Field label="할인 후 결제액 · 환불 전 (원)"><Input type="number" min="0" step="any" required value={f.paidAmount} onChange={e=>setF({...f,paidAmount:e.target.value})}/></Field><Field label="누적 환불액 (원)"><Input type="number" min="0" step="any" required value={f.refundAmount} onChange={e=>setF({...f,refundAmount:e.target.value})}/></Field></div><details open={!!initial}><summary>주문별 비용 · 모르면 빈칸</summary><div className="form-two">{Object.entries(orderCostFields).map(([k,label])=><Field key={k} label={label+' (원)'}><Input type="number" min="0" step="any" value={costs[k]} placeholder="미확인" onChange={e=>setCosts({...costs,[k]:e.target.value})}/></Field>)}</div></details><p className="notice">할인액을 비용에 다시 넣지 마세요. 취소 주문도 이미 발생한 비용은 남깁니다. 금액의 부가세 처리 기준을 통일하세요.</p><Attribution f={f} setF={x=>setF({...f,...x,channel:x.channel as typeof f.channel})} experiments={experiments}/><Field label="추적 코드 · 선택"><Input maxLength={20} autoComplete="off" placeholder="예: C7K9P2XA" value={f.trackingCode} onChange={e=>setF({...f,trackingCode:e.target.value})}/></Field><p className="notice">이 지점의 추적 코드(쿠폰·POS 태그 등)를 넣으면 코드의 캠페인·소재·게시로 귀속합니다. 게시 코드는 게시가 예약 접수·게시 확인이고 주문일이 예약일(한국 날짜) 이후일 때만 귀속하고, 아니면 귀속 없이 저장하고 사유를 알립니다. 캠페인·소재는 비워 두거나 코드와 같게 고르세요. 근거를 비우면 &apos;추적 코드 … 직접 입력&apos;으로 채웁니다.{initial?.codeAttribution&&` 지금 귀속한 추적 코드: ${initial.codeAttribution.code}(칸을 비워 두면 그대로 두고, 캠페인·소재를 바꾸면 코드 귀속만 풉니다).`}{readCodes.length>0&&` 읽거나 입력했지만 귀속하지 않은 코드: ${readCodes.join(', ')}(다시 넣으면 조회합니다).`}</p><OrderCampaignAttribution store={store} campaignId={f.campaignId} creativeId={f.creativeId} onChange={change=>setF({...f,...change})}/><Field label="유입 확인 근거 · 쿠폰/주문 코드 등"><Textarea required={!coded&&(f.channel!=='unknown'||!!f.campaignId||!!f.creativeId)} rows={2} value={f.attributionEvidence} maxLength={2000} onChange={e=>setF({...f,attributionEvidence:e.target.value})}/></Field><Field label="출처·수정 메모"><Textarea rows={2} maxLength={2000} value={f.note} onChange={e=>setF({...f,note:e.target.value})} placeholder="고객 이름·전화번호는 입력하지 마세요."/></Field><Button disabled={busy}>{busy?'저장 중…':'주문 저장'}</Button></form></DialogContent></Dialog>;
}
type OrderCreative={id:string;campaignId:string;brandId:string;storeId?:string;title?:string;caption?:string;createdAt?:string;version:number};
type OrderPublication={id:string;campaignId:string;creativeId:string;scheduledAt:string;status:string};
// 소재 이름은 실행 화면과 같다(creativeLabel): 제목, 없으면 만든 한국 시각·첫 사실 줄의 대체 라벨. 게시 이름은 소재 이름 · 예약 시각 · 상태다.
